CREATE OR REPLACE FUNCTION get_loyalty_tier(p_spend NUMERIC)
RETURNS VARCHAR AS $$
DECLARE
    v_tier VARCHAR(20);
BEGIN
    IF p_spend >= 5000 THEN
        v_tier := 'PLATINUM';
    ELSIF p_spend >= 1000 THEN
        v_tier := 'GOLD';
    ELSE
        v_tier := 'STANDARD';
    END IF;

    RETURN v_tier;
END;
$$ LANGUAGE plpgsql IMMUTABLE;
